parameters.jsCode:
const evaluation = $json.output ?? $json;

const scores = evaluation.scores;

// Preserve the original structured LLM response before deterministic classification
const rawResponse = evaluation;

const totalScore =
  scores.task_relevance +
  scores.skill_match +
  scores.gap_manageability +
  scores.role_fit +
  scores.delivery_fit +
  scores.growth_value;

const scopeOut =
  evaluation.scope_gate.status === 'out_of_scope' &&
  evaluation.scope_gate.confidence === 'high';

const hasHighConfidenceBlocker =
  Object.values(evaluation.semantic_blockers).some(
    blocker =>
      blocker.blocked === true &&
      blocker.confidence === 'high'
  );

const hasSignificantUncertainty =
  evaluation.uncertainty.significant === true;

const scopeNeedsReview =
  evaluation.scope_gate.status === 'uncertain' ||
  (
    evaluation.scope_gate.status === 'out_of_scope' &&
    evaluation.scope_gate.confidence !== 'high'
  );

let decision;

if (scopeOut) {
  decision = 'SKIP';
} else if (hasHighConfidenceBlocker) {
  decision = 'SKIP';
} else if (scopeNeedsReview) {
  decision = 'REVIEW';
} else if (hasSignificantUncertainty) {
  decision = 'REVIEW';
} else if (
  totalScore >= 14 &&
  scores.skill_match >= 2 &&
  scores.gap_manageability >= 2
) {
  decision = 'APPLY';
} else if (totalScore >= 9) {
  decision = 'REVIEW';
} else {
  decision = 'SKIP';
}

return {
  json: {
    ...evaluation,

    // AI evaluation provenance
    model_name: 'gpt-5-mini',
    prompt_version: 'semantic_prompt_v1',
    raw_response: rawResponse,

    // Deterministic Decision Engine output
    total_score: totalScore,
    decision
  }
};

const source = $('Execute a SQL query SELECT').item.json;

const errorMessage =
  $json.error?.message ??
  $json.message ??
  $json.error ??
  'AI evaluation failed or returned malformed output';

return {
  json: {
    opportunity_id: String(source.id),

    scope_gate: {
      status: 'uncertain',
      confidence: 'low',
      reason: `AI evaluation could not be completed: ${errorMessage}`
    },

    scores: {
      task_relevance: 0,
      skill_match: 0,
      gap_manageability: 0,
      role_fit: 0,
      delivery_fit: 0,
      growth_value: 0
    },

    semantic_blockers: {},

    uncertainty: {
      significant: true,
      items: [
        'AI evaluation failed or returned malformed structured output'
      ]
    },

    strengths: [],
    skill_gaps: [],

    summary: 'Manual review required because the AI evaluation could not be completed reliably.',

    model_name: 'gpt-5-mini',
    prompt_version: 'semantic_prompt_v1',

    raw_response: {
      evaluation_error: errorMessage
    },

    total_score: 0,
    decision: 'REVIEW'
  }
};;
